public struct ActivityEntry: Equatable, Hashable {
    /**
     * Stable, increasing row number.
     */
    public var id: Int64
    public var at: Int64
    public var connectionId: String
    public var connectionLabel: String
    /**
     * "search" | "read" | "send" | "grant" | "pair" | "request"
     */
    public var action: String
    /**
     * "released" | "sent" | "granted" | "denied" | "error"
     */
    public var outcome: String
    public var detail: String
    public var grantId: String?
    public var service: String
    public var account: String?
    public var count: UInt32
    public var info: ActivityInfo
    /**
     * The operation on a connector besides Gmail ("read", "send", ...), else empty.
     */
    public var op: String
    /**
     * The operation in a few words ("Read Telegram messages"), else empty.
     */
    public var opTitle: String
    /**
     * Who decided: "" (the user, or a grant), "autopilot", "bypass" or "lockdown".
     */
    public var decidedBy: String
    /**
     * What Autopilot knew (the "Automatic" filter and badge, "This was wrong").
     */
    public var autopilot: AutopilotNote?
    /**
     * What it was, as its row and its page show it.
     */
    public var label: RequestLabel?
    /**
     * What it asked, in full; `None` for entries logged before it was kept (and for pairings, grants that ended, ...).
     */
    public var request: ActivityRequest?

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(
        /**
         * Stable, increasing row number.
         */id: Int64, at: Int64, connectionId: String, connectionLabel: String, 
        /**
         * "search" | "read" | "send" | "grant" | "pair" | "request"
         */action: String, 
        /**
         * "released" | "sent" | "granted" | "denied" | "error"
         */outcome: String, detail: String, grantId: String?, service: String, account: String?, count: UInt32, info: ActivityInfo, 
        /**
         * The operation on a connector besides Gmail ("read", "send", ...), else empty.
         */op: String, 
        /**
         * The operation in a few words ("Read Telegram messages"), else empty.
         */opTitle: String, 
        /**
         * Who decided: "" (the user, or a grant), "autopilot", "bypass" or "lockdown".
         */decidedBy: String, 
        /**
         * What Autopilot knew (the "Automatic" filter and badge, "This was wrong").
         */autopilot: AutopilotNote?, 
        /**
         * What it was, as its row and its page show it.
         */label: RequestLabel? = nil, 
        /**
         * What it asked, in full; `None` for entries logged before it was kept (and for pairings, grants that ended, ...).
         */request: ActivityRequest? = nil) {
        self.id = id
        self.at = at
        self.connectionId = connectionId
        self.connectionLabel = connectionLabel
        self.action = action
        self.outcome = outcome
        self.detail = detail
        self.grantId = grantId
        self.service = service
        self.account = account
        self.count = count
        self.info = info
        self.op = op
        self.opTitle = opTitle
        self.decidedBy = decidedBy
        self.autopilot = autopilot
        self.label = label
        self.request = request
    }

    

    
}

