/**
 * What Autopilot knew about an activity entry (spec §8).
 */
public struct AutopilotNote: Equatable, Hashable {
    /**
     * The mode the request was decided or evaluated in.
     */
    public var mode: AutopilotMode
    /**
     * What Autopilot did, or would have done.
     */
    public var suggested: Verdict
    public var pApprove: Float
    public var pDeny: Float
    public var confidence: Float
    public var profileId: String
    public var profileName: String
    /**
     * Short labels of the most similar past decisions, with what the user did ("approved: …").
     */
    public var neighbours: [String]
    public var reason: String
    /**
     * "This was wrong" can be recorded for this entry (`correct_decision`).
     */
    public var correctable: Bool
    /**
     * The risk, when the model rated it.
     */
    public var risk: RiskView?
    /**
     * What the matrix decided, or would have decided in shadow (Decisions v2).
     */
    public var matrix: MatrixView?
    /**
     * The request it was about ("Ask me next time" takes it).
     */
    public var requestId: String

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(
        /**
         * The mode the request was decided or evaluated in.
         */mode: AutopilotMode, 
        /**
         * What Autopilot did, or would have done.
         */suggested: Verdict, pApprove: Float, pDeny: Float, confidence: Float, profileId: String, profileName: String, 
        /**
         * Short labels of the most similar past decisions, with what the user did ("approved: …").
         */neighbours: [String], reason: String, 
        /**
         * "This was wrong" can be recorded for this entry (`correct_decision`).
         */correctable: Bool, 
        /**
         * The risk, when the model rated it.
         */risk: RiskView? = nil, 
        /**
         * What the matrix decided, or would have decided in shadow (Decisions v2).
         */matrix: MatrixView? = nil, 
        /**
         * The request it was about ("Ask me next time" takes it).
         */requestId: String = "") {
        self.mode = mode
        self.suggested = suggested
        self.pApprove = pApprove
        self.pDeny = pDeny
        self.confidence = confidence
        self.profileId = profileId
        self.profileName = profileName
        self.neighbours = neighbours
        self.reason = reason
        self.correctable = correctable
        self.risk = risk
        self.matrix = matrix
        self.requestId = requestId
    }

    

    
}

