/**
 * One connection's Autopilot settings.
 */
public struct ConnectionAutopilot: Equatable, Hashable {
    public var connectionId: String
    /**
     * The connection's own mode when no bypass runs; `None` = it follows the global mode.
     */
    public var baseMode: AutopilotMode?
    /**
     * A bypass of this connection runs until then (`i64::MAX`: until the user turns it off).
     */
    public var bypassUntil: Int64?
    /**
     * When that bypass started.
     */
    public var bypassSince: Int64?
    /**
     * Its own Overnight runs until then (`i64::MAX`: until the user turns it off).
     */
    public var overnightUntil: Int64?
    public var overnightSince: Int64?
    /**
     * What applies to its requests now (global lockdown and bypass included).
     */
    public var mode: AutopilotMode
    /**
     * The profile its decisions train (the default profile when it has none of its own).
     */
    public var profileId: String

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(connectionId: String, 
        /**
         * The connection's own mode when no bypass runs; `None` = it follows the global mode.
         */baseMode: AutopilotMode?, 
        /**
         * A bypass of this connection runs until then (`i64::MAX`: until the user turns it off).
         */bypassUntil: Int64?, 
        /**
         * When that bypass started.
         */bypassSince: Int64?, 
        /**
         * Its own Overnight runs until then (`i64::MAX`: until the user turns it off).
         */overnightUntil: Int64? = nil, overnightSince: Int64? = nil, 
        /**
         * What applies to its requests now (global lockdown and bypass included).
         */mode: AutopilotMode, 
        /**
         * The profile its decisions train (the default profile when it has none of its own).
         */profileId: String) {
        self.connectionId = connectionId
        self.baseMode = baseMode
        self.bypassUntil = bypassUntil
        self.bypassSince = bypassSince
        self.overnightUntil = overnightUntil
        self.overnightSince = overnightSince
        self.mode = mode
        self.profileId = profileId
    }

    

    
}

