     * Asked because of a hard obligation (no permit could cover it).
     */
    public var hard: Bool
    public var zone: ZoneChoice
    /**
     * 0..=3.
     */
    public var level: UInt8
    /**
     * "Auto · Mine · Undoable".
     */
