         */hard: Bool, zone: ZoneChoice, 
        /**
         * 0..=3.
         */level: UInt8, 
        /**
         * "Auto · Mine · Undoable".
         */line: String, 
        /**
         * Recorded only: something else decided.
         */shadow: Bool) {
        self.outcome = outcome
        self.hard = hard
        self.zone = zone
        self.level = level
        self.line = line
        self.shadow = shadow
    }

    

    
}

