public struct PendingItem: Equatable, Hashable {
    public var kind: PendingKind
    public var id: String
    /**
     * Plain-language headline (used by notifications); the app builds its own from the fields below.
     */
    public var title: String
    public var subtitle: String
    public var createdAt: Int64
    public var connectionId: String
    public var connectionLabel: String
    /**
     * "search" | "read" | "send" | "grant" | "pair"
     */
    public var action: String
    /**
     * How many messages / recipients the operation covers (1 for grants and pairings).
     */
    public var count: UInt32
    /**
     * The connector this is about, e.g. "gmail", and the account within it when known.
     */
    public var service: String
    public var account: String?
    /**
     * Unix seconds until which the AI is still waiting; later approvals are "late" (see `approve`).
     */
    public var waitUntil: Int64?
    /**
     * The operation on a connector besides Gmail ("read", "send", ...), else empty.
     */
    public var op: String
    /**
     * The operation in a few words ("Read Telegram messages"), else empty (Gmail, pairings).
     */
    public var opTitle: String
    /**
     * What Autopilot would do, in one line for the notification ("Autopilot would approve · 97%"); `None` when it
     * did not judge (no model).
     */
    public var suggestion: String?
    /**
     * What approving does, in one sentence (see [`ApprovalView::headline`]); empty for pairings and other phones.
     */
    public var headline: String
    /**
     * Can be approved without opening it, from the notification or with "Approve all" (`approve_quick`): it is not
     * asked every time and nothing in it needs a closer look.
     */
    public var quick: Bool
    /**
     * What the request is, as every screen shows it (see [`RequestLabel`]); `None` for pairings and other phones.
     */
    public var label: RequestLabel?
    /**
     * The request became a ticket (the agent does not wait for it): its window, and a "Why?" and the agent's answer.
     */
    public var ticket: TicketView?
    /**
     * An Instant request the reviewer can move to later (`decide_later`).
     */
    public var canDefer: Bool
    /**
     * Parked by Overnight for the morning (Decisions v2, 01 §11): no notification and no reminder before then; the
     * morning digest (`overnight_digest`) covers it.
     */
    public var parkedUntil: Int64?
    /**
     * The task its agent was working on when it was parked or asked (the digest and the inbox group by it).
     */
    public var taskId: String?
    public var taskTitle: String?
    /**
     * "Approve all" may cover it: what the matrix asked is soft and below L3 (03 §5.2: batch never crosses L3).
     */
    public var batchable: Bool
    /**
     * An agent proposes a task: its envelope, which the owner may narrow before approving (`approve_task`).
     */
    public var taskProposal: TaskView?
    /**
     * Others in the owner's Circle decide it too ("Needs Alex too", "Alex approved, waiting for you").
     */
    public var circle: CircleProgress?
    /**
     * Parked by Overnight: never notified on arrival (an Overnight without an end parks until now, so the apps check
     * this, not `parked_until`).
     */
    public var parked: Bool

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(kind: PendingKind, id: String, 
        /**
         * Plain-language headline (used by notifications); the app builds its own from the fields below.
         */title: String, subtitle: String, createdAt: Int64, connectionId: String, connectionLabel: String, 
        /**
         * "search" | "read" | "send" | "grant" | "pair"
         */action: String, 
        /**
         * How many messages / recipients the operation covers (1 for grants and pairings).
         */count: UInt32, 
        /**
         * The connector this is about, e.g. "gmail", and the account within it when known.
         */service: String, account: String?, 
        /**
         * Unix seconds until which the AI is still waiting; later approvals are "late" (see `approve`).
         */waitUntil: Int64?, 
        /**
         * The operation on a connector besides Gmail ("read", "send", ...), else empty.
         */op: String, 
        /**
         * The operation in a few words ("Read Telegram messages"), else empty (Gmail, pairings).
         */opTitle: String, 
        /**
         * What Autopilot would do, in one line for the notification ("Autopilot would approve · 97%"); `None` when it
         * did not judge (no model).
         */suggestion: String?, 
        /**
         * What approving does, in one sentence (see [`ApprovalView::headline`]); empty for pairings and other phones.
         */headline: String = "", 
        /**
         * Can be approved without opening it, from the notification or with "Approve all" (`approve_quick`): it is not
         * asked every time and nothing in it needs a closer look.
         */quick: Bool = false, 
        /**
         * What the request is, as every screen shows it (see [`RequestLabel`]); `None` for pairings and other phones.
         */label: RequestLabel? = nil, 
        /**
         * The request became a ticket (the agent does not wait for it): its window, and a "Why?" and the agent's answer.
         */ticket: TicketView? = nil, 
        /**
         * An Instant request the reviewer can move to later (`decide_later`).
         */canDefer: Bool = false, 
        /**
         * Parked by Overnight for the morning (Decisions v2, 01 §11): no notification and no reminder before then; the
         * morning digest (`overnight_digest`) covers it.
         */parkedUntil: Int64? = nil, 
        /**
         * The task its agent was working on when it was parked or asked (the digest and the inbox group by it).
         */taskId: String? = nil, taskTitle: String? = nil, 
        /**
         * "Approve all" may cover it: what the matrix asked is soft and below L3 (03 §5.2: batch never crosses L3).
         */batchable: Bool = false, 
        /**
         * An agent proposes a task: its envelope, which the owner may narrow before approving (`approve_task`).
         */taskProposal: TaskView? = nil, 
        /**
         * Others in the owner's Circle decide it too ("Needs Alex too", "Alex approved, waiting for you").
         */circle: CircleProgress? = nil, 
        /**
         * Parked by Overnight: never notified on arrival (an Overnight without an end parks until now, so the apps check
         * this, not `parked_until`).
         */parked: Bool = false) {
        self.kind = kind
        self.id = id
        self.title = title
        self.subtitle = subtitle
        self.createdAt = createdAt
        self.connectionId = connectionId
        self.connectionLabel = connectionLabel
        self.action = action
        self.count = count
        self.service = service
        self.account = account
        self.waitUntil = waitUntil
        self.op = op
        self.opTitle = opTitle
        self.suggestion = suggestion
        self.headline = headline
        self.quick = quick
        self.label = label
        self.ticket = ticket
        self.canDefer = canDefer
        self.parkedUntil = parkedUntil
        self.taskId = taskId
        self.taskTitle = taskTitle
        self.batchable = batchable
        self.taskProposal = taskProposal
        self.circle = circle
        self.parked = parked
    }

    

    
}

